  --background: #e9eef8;
  --foreground: #0f172a;
  --card: rgba(255, 255, 255, 0.9);
  --card-foreground: #0f172a;
  --popover: rgba(255, 255, 255, 0.96);
  --popover-foreground: #0f172a;
  --primary: #2563eb;
  --primary-foreground: #ffffff;
  --secondary: #e9eefc;
  --secondary-foreground: #1e293b;
  --muted-surface: #eef1f5;
  --muted-foreground: #64748b;
  --accent: #dbeafe;
  --accent-foreground: #1d4ed8;
  --destructive: #ef4444;
  --border: rgba(203, 213, 225, 0.6);
  --input: #dde3ee;
  --ring: #2563eb;
  --sidebar: rgba(248, 250, 255, 0.78);
  --sidebar-foreground: #0f172a;
  --sidebar-primary: #2563eb;
  --sidebar-primary-foreground: #ffffff;
  --sidebar-accent: #e9eefc;
  --sidebar-accent-foreground: #1e293b;
  --sidebar-border: rgba(214, 222, 238, 0.7);
  --sidebar-ring: #2563eb;
}

/*
 * Blank-diorama theme. Same glass language, warmer near-white clay.
 * White is still the primary material; sandstone is the muted ground role.
 */
html[data-theme='blank'],
[data-theme='blank'] {
  --background: #f6efe4;
  --foreground: #2a241f;
  --secondary: #f3eadc;
  --secondary-foreground: #3f2f22;
  --accent: #f3e0c4;
  --accent-foreground: #9a3412;
  --primary: #c2410c;
  --primary-foreground: #fff7ed;
  --ring: #c2410c;
  --blue: #c2410c;
  --blue-deep: #9a3412;
  --muted-surface: #efe4d2;
  --muted-foreground: #6b5b4e;
  --sidebar-primary: #c2410c;
  --sidebar-accent: #f3eadc;
  --clay-ground: #efe4d2;
  --clay-road: #d4b896;
  --clay-grass: #d7e3b8;
  --clay-wall: #f6efe4;
  --clay-roof: #c2410c;
  --clay-accent: #c2410c;
  --clay-yellow: #e2a334;
  --clay-cardboard: #c4a07a;
  --clay-tree: #7dae6a;
  --clay-tire: #2a241f;
  --clay-ao: #4a3728;
  --clay-sky: #f3ead8;

  --mokei-base: #f6efe4;
  --mokei-accent-1: #c2410c;
  --mokei-accent-2: #e2a334;
  --mokei-accent-3: #c2410c;
  --mokei-detail-dark: #2a241f;
  --mokei-detail-mid: #716b64;
  --mokei-detail-light: #bdb6ad;
  --mokei-ground: #efe4d2;
}

/*
 * Quarry theme — Rock-locked palette. Orange and teal are gone.
 *
 *   base        warm white     #F7F5F0   primary material / UI surfaces
 *   accent1     azurite        #2B59E8   features, links, brand, UI primary
 *   accent2     signal yellow  #F2B705   permission / warning / active only
 *   accent3     slate          #3B4552   secondary trim
 *   detail.dark near-black     #1C1F24   dark end of the detail ramp
 *   ground      sandstone      #E6D5B8   ground and rock faces only
 *
 * Signal yellow is a surface, never ink on white. --warning-foreground is
 * near-black so yellow badges and chips stay readable.
 */
html[data-theme='quarry'],
[data-theme='quarry'] {
  color-scheme: light;

  --fs: 0.92;
  --track: -0.012em;

  --ink: #1c1f24;
  --ink-2: #3b4552;
  --muted: #6b7280;
  --muted-2: #8b919a;
  --hair: rgba(28, 31, 36, 0.14);
  --blue: #2b59e8;
  --blue-deep: #1e48c7;

  --glass-bg: rgba(255, 255, 255, 0.9);
  --glass-border: rgba(255, 255, 255, 0.95);
  --glass-shadow: 0 1px 2px rgba(28, 31, 36, 0.04), 0 8px 24px rgba(28, 31, 36, 0.08);
  --glass-blur: 20px;
  --glass-saturate: 1.25;
  --topbar-bg: rgba(247, 245, 240, 0.82);
  --topbar-border: rgba(59, 69, 82, 0.16);
  --topbar-shadow: 0 6px 20px rgba(28, 31, 36, 0.04);

  --background: #f7f5f0;
  --foreground: #1c1f24;
  --card: rgba(255, 255, 255, 0.92);
  --card-foreground: #1c1f24;
  --popover: rgba(255, 255, 255, 0.96);
  --popover-foreground: #1c1f24;
  --primary: #2b59e8;
  --primary-foreground: #ffffff;
  --secondary: #e8e4dc;
  --secondary-foreground: #3b4552;
  --muted-surface: #efebe3;
  --muted-foreground: #5c6570;
  --accent: #d6e0fb;
  --accent-foreground: #2b59e8;
  --destructive: #b42318;
  --border: rgba(28, 31, 36, 0.14);
  --input: #e4e0d8;
  --ring: #2b59e8;

  --radius: 0.75rem;

  --success: #15803d;
  --success-foreground: #dcf5e3;
  /* Yellow surface + dark ink. Never yellow text on white. */
  --warning: #f2b705;
  --warning-foreground: #1c1f24;
  --info: #2b59e8;
  --info-foreground: #d6e0fb;

  --chart-1: #2b59e8;
  --chart-2: #3b4552;
  --chart-3: #f2b705;
  --chart-4: #e6d5b8;
  --chart-5: #1c1f24;

